"use strict";(self.webpackChunkwoodpecker=self.webpackChunkwoodpecker||[]).push([["3268"],{71490(e){e.exports=JSON.parse('{"name":"Oxlint","slug":"oxlint","url":"https://codeberg.org/adamlui/drone-oxlint","icon":"https://cdn.staticdelivr.com/gl/adamlui/drone-oxlint/17c8684377/assets/images/icons/oxlint/teal-white-on-black/rounded/icon200.png","description":"Plugin to run Oxlint on your repo.","docs":"<a id=\\"top\\" href=\\"https://codeberg.org/adamlui/drone-oxlint/releases\\">\\n    <img alt=\\"[Latest Build]\\" src=\\"https://img.shields.io/docker/v/adamlui/drone-oxlint?logo=icinga&amp;label=Latest+build&amp;style=for-the-badge&amp;color=32fcee\\"></a>\\n<a href=\\"https://codeberg.org/adamlui/drone-oxlint/src/branch/main/docs/LICENSE.md\\">\\n    <img alt=\\"[License: MIT]\\" src=\\"https://img.shields.io/badge/License-MIT-f1f20a.svg?logo=internetarchive&amp;logoColor=white&amp;style=for-the-badge\\"></a>\\n<a href=\\"https://hub.docker.com/r/adamlui/drone-oxlint\\">\\n    <img alt=\\"[Docker Hub]\\" src=\\"https://img.shields.io/docker/pulls/adamlui/drone-oxlint?style=for-the-badge&amp;logo=docker&amp;logoColor=white&amp;label=Downloads&amp;color=000000\\"></a><img src=\\"https://cdn.staticdelivr.com/gl/adamlui/drone-oxlint/bdef770ad8/assets/images/screenshots/woodpecker-demo.png\\"><hr>\\n<h2 id=\\"quick-start\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/ic/sharp-install-desktop.svg?color=%23ffffff\\"><img height=\\"30\\" width=\\"27\\" align=\\"top\\" src=\\"https://api.iconify.design/ic/sharp-install-desktop.svg?color=%232b2b2a\\"></picture>\\n    Quick start\\n</h2><pre><code class=\\"language-yaml\\">when:\\n  - event: manual\\n  - event: [pull_request, push]\\n    path: { include: [\'**/*.{cjs,cts,js,jsx,mjs,mts,ts,tsx}\'] }\\n\\nsteps:\\n  - name: oxlint\\n    image: adamlui/drone-oxlint:v1.7.0\\n</code></pre>\\n<hr>\\n<h2 id=\\"settings\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/fluent/settings-cog-multiple-24-filled.svg?color=%23ffffff\\"><img height=\\"30\\" width=\\"23\\" align=\\"top\\" src=\\"https://api.iconify.design/fluent/settings-cog-multiple-24-filled.svg?color=%232b2b2a\\"></picture>\\n    Settings (21)\\n</h2><blockquote>\\n<p><strong>NOTE</strong>&nbsp; YAML settings override matching config file settings.</p>\\n</blockquote>\\n<h4 id=\\"example-config\\">Example</h4><pre><code class=\\"language-yaml\\">  - name: oxlint\\n    image: adamlui/drone-oxlint:v1.7.0\\n    settings:\\n      config: oxlint.config.ts\\n      warn: no-console\\n      deny: no-eval\\n      plugins: import nextjs\\n      max_warnings: 10\\n      debug: true\\n</code></pre>\\n<details open=\\"\\"><summary id=\\"settings-oxlint\\"><picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/mdi/cog.svg?color=%23ffffff\\"><img width=\\"13\\" height=\\"27\\" align=\\"top\\" src=\\"https://api.iconify.design/mdi/cog.svg?color=%232b2b2a\\"></picture> <b>Oxlint (9)</b></summary><br><table>\\n<thead>\\n<tr>\\n<th align=\\"left\\">Setting</th>\\n<th align=\\"left\\">Description</th>\\n<th align=\\"left\\">Default</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td align=\\"left\\"><code>config</code></td>\\n<td align=\\"left\\">Path to an <a href=\\"https://oxc.rs/docs/guide/usage/linter/config-file-reference\\">Oxlint</a> or <a href=\\"https://eslint.org/docs/v8.x/use/configure/configuration-files\\">ESLint &lt;9</a> config file.</td>\\n<td align=\\"left\\"><em>auto-detected</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>no_config</code></td>\\n<td align=\\"left\\">Disable auto-discover config file.</td>\\n<td align=\\"left\\"><code>false</code></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>oxlint_args</code></td>\\n<td align=\\"left\\">Additional raw args passed verbatim to the Oxlint <a href=\\"https://oxc.rs/docs/guide/usage/linter/cli.html\\">CLI</a> (e.g. <code>--fix --quiet</code>).</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>plugins</code></td>\\n<td align=\\"left\\">Whitespace-separated list of <a href=\\"https://oxc.rs/docs/guide/usage/linter/plugins.html\\">plugins</a> to enable (e.g. <code>nextjs import</code>).</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>plugins_disable</code></td>\\n<td align=\\"left\\">Whitespace-separated list of <a href=\\"https://oxc.rs/docs/guide/usage/linter/plugins.html\\">plugins</a> to disable (e.g. <code>typescript</code>).</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>format</code></td>\\n<td align=\\"left\\">Lint result <a href=\\"https://oxc.rs/docs/guide/usage/linter/output-formats\\">output format</a> (e.g. <code>agent</code>, <code>json</code>).</td>\\n<td align=\\"left\\"><code>default</code></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>base_branch</code></td>\\n<td align=\\"left\\">Base branch that PRs are compared against.</td>\\n<td align=\\"left\\">PR target branch</td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>version</code></td>\\n<td align=\\"left\\">Oxlint <a href=\\"https://www.npmjs.com/package/oxlint?activeTab=versions\\">version</a> to install. Accepts a <a href=\\"https://semver.org/spec/v2.0.0.html\\">SemVer</a> <a href=\\"https://github.com/npm/node-semver#ranges\\">pattern</a>.</td>\\n<td align=\\"left\\"><code>latest</code></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>working_directory</code></td>\\n<td align=\\"left\\">Directory to run Oxlint from.</td>\\n<td align=\\"left\\">repo root</td>\\n</tr>\\n</tbody></table>\\n</details><details><summary id=\\"settings-file-matching\\"><picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/mdi/cog.svg?color=%23ffffff\\"><img width=\\"13\\" height=\\"27\\" align=\\"top\\" src=\\"https://api.iconify.design/mdi/cog.svg?color=%232b2b2a\\"></picture> <b>File matching (5)</b></summary><br><table>\\n<thead>\\n<tr>\\n<th align=\\"left\\">Setting</th>\\n<th align=\\"left\\">Description</th>\\n<th align=\\"left\\">Default</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td align=\\"left\\"><code>files</code></td>\\n<td align=\\"left\\">Whitespace-separated list of glob patterns to include (e.g. <code>src/**</code>).</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>ignore_patterns</code></td>\\n<td align=\\"left\\">Whitespace-separated list of glob patterns to exclude (e.g. <code>dist/** build/**</code>).</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>ignore_path</code></td>\\n<td align=\\"left\\">Path to an ignore file (e.g. <code>.oxlintignore</code>, <code>.eslintignore</code>).</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>extensions</code></td>\\n<td align=\\"left\\">Comma-separated file extensions to lint on pull requests.</td>\\n<td align=\\"left\\"><code>cjs,cts,js,jsx,mjs,mts,ts,tsx</code></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>all_files</code></td>\\n<td align=\\"left\\">Lint all files, not just changed files on pull requests.</td>\\n<td align=\\"left\\"><code>false</code></td>\\n</tr>\\n</tbody></table>\\n</details><details><summary id=\\"settings-rules\\"><picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/mdi/cog.svg?color=%23ffffff\\"><img width=\\"13\\" height=\\"27\\" align=\\"top\\" src=\\"https://api.iconify.design/mdi/cog.svg?color=%232b2b2a\\"></picture> <b>Rules &amp; warnings (5)</b></summary><br><table>\\n<thead>\\n<tr>\\n<th align=\\"left\\">Setting</th>\\n<th align=\\"left\\">Description</th>\\n<th align=\\"left\\">Default</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td align=\\"left\\"><code>allow</code></td>\\n<td align=\\"left\\">Whitespace-separated list of <a href=\\"https://oxc.rs/docs/guide/usage/linter/rules.html\\">rules</a> or <a href=\\"https://oxc.rs/docs/guide/usage/linter/config.html#enable-groups-of-rules-with-categories\\">categories</a> to allow.</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>warn</code></td>\\n<td align=\\"left\\">Whitespace-separated list of <a href=\\"https://oxc.rs/docs/guide/usage/linter/rules.html\\">rules</a> or <a href=\\"https://oxc.rs/docs/guide/usage/linter/config.html#enable-groups-of-rules-with-categories\\">categories</a> to warn.</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>deny</code></td>\\n<td align=\\"left\\">Whitespace-separated list of <a href=\\"https://oxc.rs/docs/guide/usage/linter/rules.html\\">rules</a> or <a href=\\"https://oxc.rs/docs/guide/usage/linter/config.html#enable-groups-of-rules-with-categories\\">categories</a> to deny.</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>deny_warnings</code></td>\\n<td align=\\"left\\">Fail if any warnings are emitted (alias for <code>max_warnings: 0</code>).</td>\\n<td align=\\"left\\"><code>false</code></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>max_warnings</code></td>\\n<td align=\\"left\\">Fail if more than this many warnings are emitted.</td>\\n<td align=\\"left\\"><em>none</em></td>\\n</tr>\\n</tbody></table>\\n</details><details><summary id=\\"settings-plugin\\"><picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/mdi/cog.svg?color=%23ffffff\\"><img width=\\"13\\" height=\\"27\\" align=\\"top\\" src=\\"https://api.iconify.design/mdi/cog.svg?color=%232b2b2a\\"></picture> <b>Plugin (2)</b></summary><br><table>\\n<thead>\\n<tr>\\n<th align=\\"left\\">Setting</th>\\n<th align=\\"left\\">Description</th>\\n<th align=\\"left\\">Default</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td align=\\"left\\"><code>debug</code></td>\\n<td align=\\"left\\">Enable shell tracing (<code>set -x</code>) of the plugin entrypoint.</td>\\n<td align=\\"left\\"><code>false</code></td>\\n</tr>\\n<tr>\\n<td align=\\"left\\"><code>never_fail</code></td>\\n<td align=\\"left\\">Exit <code>0</code> regardless of lint errors (so CI step always passes).</td>\\n<td align=\\"left\\"><code>false</code></td>\\n</tr>\\n</tbody></table>\\n</details><hr>\\n<h2 id=\\"shield-embed\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/boxicons/code-alt-filled.svg?color=%23ffffff\\"><img height=\\"30\\" width=\\"30\\" align=\\"top\\" src=\\"https://api.iconify.design/boxicons/code-alt-filled.svg?color=%232b2b2a\\"></picture>\\n    Shield embed\\n</h2><p><a href=\\"https://codeberg.org/adamlui/drone-oxlint/#readme\\"><img height=\\"32\\" alt=\\"[Linted by drone-oxlint]\\" src=\\"https://img.shields.io/badge/Linted_by-drone--oxlint-black?logo=drone&amp;logoColor=white&amp;labelColor=464646&amp;style=for-the-badge\\"></a></p>\\n<h4>HTML</h4>\\n<pre><code class=\\"language-html\\">&lt;a target=\\"_blank\\" href=\\"https://codeberg.org/adamlui/drone-oxlint/#readme\\"&gt;\\n    &lt;img height=32 alt=\\"[Linted by drone-oxlint]\\" src=\\"https://img.shields.io/badge/Linted_by-drone--oxlint-black?logo=drone&amp;logoColor=white&amp;labelColor=464646&amp;style=for-the-badge\\"&gt;&lt;/a&gt;\\n</code></pre>\\n<h4>Markdown</h4>\\n<pre><code class=\\"language-md\\">[![[Linted by drone-oxlint]](https://img.shields.io/badge/Linted_by-drone--oxlint-black?logo=drone&amp;logoColor=white&amp;labelColor=464646&amp;style=for-the-badge)](https://codeberg.org/adamlui/drone-oxlint/#readme)\\n</code></pre>\\n<hr>\\n<h2 id=\\"contributing\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/octicon/people-16.svg?color=%23ffffff\\"><img width=\\"27\\" align=\\"top\\" src=\\"https://api.iconify.design/octicon/people-16.svg?color=%232b2b2a\\"></picture>\\n    Contributing\\n</h2><details><summary>All contributions welcome! See <a href=\\"https://codeberg.org/adamlui/drone-oxlint/src/branch/main/docs/CONTRIBUTING.md\\"><code>docs/CONTRIBUTING.md</code></a> to get started.</summary><br><ol>\\n<li><strong>Fork</strong> the repo &gt; create a branch from <code>main</code>.</li>\\n<li><strong>Make your change</strong> (one contribution per branch).</li>\\n<li><strong>Open a pull request</strong> &gt; describe what you changed and why.</li>\\n</ol>\\n<h3 id=\\"dev-setup\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/tabler/device-laptop.svg?color=%23ffffff\\"><img width=\\"25\\" align=\\"top\\" src=\\"https://api.iconify.design/tabler/device-laptop.svg?color=%232b2b2a\\"></picture>\\n    Dev setup\\n</h3><p>You\'ll need <a href=\\"https://docs.docker.com/get-started/\\">Docker</a> and (for local pipeline testing) the <a href=\\"https://docs.drone.io/quickstart/cli/\\">Drone CLI</a>.</p>\\n<pre><code class=\\"language-bash\\">git clone https://codeberg.org/adamlui/drone-oxlint.git\\ncd drone-oxlint\\n</code></pre>\\n<p>The plugin is built from the <a href=\\"https://docs.docker.com/reference/dockerfile\\">Dockerfile</a> and runs via <code>src/entrypoint.sh</code> + <code>src/utils.sh</code>. If you change any of these, rebuild the image:</p>\\n<pre><code class=\\"language-bash\\">docker build -t adamlui/drone-oxlint:dev .\\n</code></pre>\\n<h3 id=\\"test-your-change\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/ph/flask-bold.svg?color=%23ffffff\\"><img height=\\"26\\" width=\\"21\\" align=\\"top\\" src=\\"https://api.iconify.design/ph/flask-bold.svg?color=%232b2b2a\\"></picture>\\n    Test your change\\n</h3><p>Run the example pipeline locally:</p>\\n<pre><code class=\\"language-bash\\">drone exec --pipeline default\\n</code></pre>\\n<p>No Drone CLI? Test the image directly:</p>\\n<pre><code class=\\"language-bash\\">docker run --rm -v \\"$PWD:/app\\" -w /app adamlui/drone-oxlint:dev\\n</code></pre>\\n<hr>\\n<h2 id=\\"financial-contributions\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/mdi/heart-outline.svg?color=%23ffffff\\"><img width=\\"27\\" align=\\"top\\" src=\\"https://api.iconify.design/mdi/heart-outline.svg?color=%232b2b2a\\"></picture>\\n    Financial contributions\\n</h2><p>If you find this project useful, you can support its development:</p>\\n<p><a href=\\"https://paypal.me/adamlui\\"><img alt=\\"[PayPal]\\" src=\\"https://img.shields.io/badge/PayPal-Donate-00457C?style=for-the-badge&amp;logo=paypal&amp;logoColor=white\\"></a>\\n<a href=\\"https://ko-fi.com/adamlui\\"><img alt=\\"[Ko-fi]\\" src=\\"https://img.shields.io/badge/Ko--fi-Support-FF5E5B?style=for-the-badge&amp;logo=ko-fi&amp;logoColor=white\\"></a></p>\\n</details><hr>\\n<h2 id=\\"license\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/ic/baseline-account-balance.svg?color=%23ffffff\\"><img height=\\"30\\" width=\\"27\\" align=\\"top\\" src=\\"https://api.iconify.design/ic/baseline-account-balance.svg?color=%232b2b2a\\"></picture>\\n    License\\n</h2><details><summary>Copyright \xa9 2026 <a href=\\"https://codeberg.org/adamlui\\"><b>Adam Lui</b></a> under the <a href=\\"https://codeberg.org/adamlui/drone-oxlint/src/branch/main/docs/LICENSE.md\\"><b>MIT license</b></a>.</summary><br><p>Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the \\"Software\\"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:</p>\\n<p>The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.</p>\\n<p>THE SOFTWARE IS PROVIDED \\"AS IS\\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE</p>\\n</details><hr>\\n<h2 id=\\"related\\">\\n    <picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://api.iconify.design/bxs/package.svg?color=%23ffffff\\"><img height=\\"30\\" width=\\"29\\" align=\\"top\\" src=\\"https://api.iconify.design/bxs/package.svg?color=%232b2b2a\\"></picture>\\n    Related\\n</h2><h3><a href=\\"https://codeberg.org/adamlui/drone-eslint/#readme\\"><picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://cdn.staticdelivr.com/gl/adamlui/drone-oxlint/1635f70f1b/assets/images/icons/drone/white/icon64.png\\"><img width=\\"15\\" src=\\"https://cdn.staticdelivr.com/gl/adamlui/drone-oxlint/1635f70f1b/assets/images/icons/drone/black/icon64.png\\"></picture> drone-eslint</a></h3>\\n<details><summary>Drone / Harness / Woodpecker plugin for running ESLint (auto-installs plugins!)</summary><br><blockquote>\\n<p><a href=\\"https://codeberg.org/adamlui/drone-eslint/#readme\\"><img width=\\"555\\" src=\\"https://cdn.staticdelivr.com/gl/adamlui/drone-eslint/230a32f493/assets/images/screenshots/woodpecker-demo.png\\"></a></p>\\n</blockquote>\\n<blockquote>\\n<p><a href=\\"#quick-start\\"><b>Install</b></a> / <a href=\\"https://codeberg.org/adamlui/drone-eslint/#readme\\">Readme</a> / <a href=\\"https://codeberg.org/adamlui/drone-eslint/#settings\\">Settings</a></p>\\n</blockquote>\\n</details><h3><a href=\\"https://codeberg.org/adamlui/eslint-plugin-woodpecker/#readme\\"><img height=\\"15\\" width=\\"auto\\" src=\\"https://cdn.staticdelivr.com/gl/adamlui/eslint-plugin-greasemonkey/e9128375d4/assets/images/icons/eslint/purple/icon16.png\\"> eslint-plugin-woodpecker</a></h3>\\n<details><summary>ESLint rules for Woodpecker CI files (including shell commands!)</summary><br><blockquote>\\n<p><a href=\\"https://codeberg.org/adamlui/eslint-plugin-woodpecker/#readme\\"><img width=\\"555\\" src=\\"https://cdn.staticdelivr.com/gl/adamlui/eslint-plugin-woodpecker/9e93ab43/assets/images/screenshots/vs-code/squiggles.png\\"></a></p>\\n</blockquote>\\n<blockquote>\\n<p><a href=\\"https://codeberg.org/adamlui/eslint-plugin-woodpecker/#installation\\"><b>Install</b></a> / <a href=\\"https://codeberg.org/adamlui/eslint-plugin-woodpecker/#readme\\">Readme</a> / <a href=\\"https://codeberg.org/adamlui/eslint-plugin-woodpecker/#supported-rules\\">Supported rules</a></p>\\n</blockquote>\\n</details><h3><a href=\\"https://codeberg.org/adamlui/eslint-plugin-constructors/#readme\\"><img height=\\"15\\" width=\\"auto\\" src=\\"https://cdn.staticdelivr.com/gl/adamlui/eslint-plugin-greasemonkey/e9128375d4/assets/images/icons/eslint/purple/icon16.png\\"> eslint-plugin-constructors</a></h3>\\n<details><summary>ESLint rules for JavaScript constructor usage.</summary><br><blockquote>\\n<p><a href=\\"https://codeberg.org/adamlui/eslint-plugin-constructors/#readme\\"><img width=\\"555\\" src=\\"https://cdn.staticdelivr.com/gl/adamlui/eslint-plugin-constructors/6eeba7b2cb/assets/images/screenshots/vs-code/squiggles.png\\"></a></p>\\n</blockquote>\\n<blockquote>\\n<p><a href=\\"https://codeberg.org/adamlui/eslint-plugin-constructors/#installation\\"><b>Install</b></a> / <a href=\\"https://codeberg.org/adamlui/eslint-plugin-constructors/#readme\\">Readme</a> / <a href=\\"https://codeberg.org/adamlui/eslint-plugin-constructors/#supported-rules\\">Supported rules</a></p>\\n</blockquote>\\n</details><img height=\\"10\\" width=\\"100%\\" src=\\"https://cdn.staticdelivr.com/gl/adamlui/ai-web-extensions/d11d2ee/assets/images/separators/gradient-aqua.png\\"><div align=\\"center\\"><p><picture><source media=\\"(prefers-color-scheme: dark)\\" srcset=\\"https://cdn.staticdelivr.com/gl/adamlui/js-utils/6b0d399/assets/images/icons/tag/white/icon16.svg\\"><img height=\\"14\\" src=\\"https://cdn.staticdelivr.com/gl/adamlui/js-utils/6b0d399/assets/images/icons/tag/dark-gray/icon16.svg\\"></picture>\\n<a href=\\"https://codeberg.org/adamlui/drone-oxlint/releases\\"><b>Latest releases</b></a> / <a href=\\"https://codeberg.org/adamlui/drone-oxlint/issues/new\\">Report a bug</a> / <a href=\\"#top\\">Back to top \u2191</a></p>\\n</div>\\n","tags":["security","oxlint","javascript","typescript","code-quality"],"author":"Adam Lui","containerImage":"adamlui/drone-oxlint","containerImageUrl":"https://hub.docker.com/r/adamlui/drone-oxlint","verified":false,"iconDataUrl":"data:image/png;base64,","latestRelease":{"tag":"1.7.0","url":"https://codeberg.org/adamlui/drone-oxlint/releases/tag/v1.7.0"}}')}}]);